CREATE TABLE public.staff_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_kind text NOT NULL,source_id text NOT NULL,city_id uuid,department text NOT NULL CHECK(department IN ('orders','dispatch','riders','partners','finance','support')),title text NOT NULL,next_action text,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','blocked','review','resolved')),assignee_id uuid,backup_id uuid,supervisor_id uuid,due_at timestamptz,blocked_reason text,resolution text,resolved_at timestamptz,resolved_by uuid,reopen_count integer NOT NULL DEFAULT 0,escalation_level integer NOT NULL DEFAULT 0,last_escalated_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(source_kind,source_id));
GRANT SELECT ON public.staff_cases TO authenticated; GRANT ALL ON public.staff_cases TO service_role; ALTER TABLE public.staff_cases ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.staff_case_allowed(_city uuid,_dept text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.staff_city_allowed(_city) AND _dept IN ('orders','dispatch','riders','partners','finance','support') AND (public.has_permission(auth.uid(),_dept) OR (public.has_permission(auth.uid(),'audit') AND _dept<>'finance')) $$;
CREATE POLICY "Scoped cases read" ON public.staff_cases FOR SELECT TO authenticated USING(public.staff_case_allowed(city_id,department));
CREATE INDEX staff_cases_queue ON public.staff_cases(city_id,department,status,due_at,id); CREATE INDEX staff_cases_assignee ON public.staff_cases(assignee_id,status);
CREATE TABLE public.staff_case_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),case_id uuid NOT NULL REFERENCES public.staff_cases(id) ON DELETE CASCADE,actor_id uuid,action text NOT NULL,note text,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.staff_case_events TO authenticated; GRANT ALL ON public.staff_case_events TO service_role; ALTER TABLE public.staff_case_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Scoped case history" ON public.staff_case_events FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.staff_cases c WHERE c.id=case_id AND public.staff_case_allowed(c.city_id,c.department))); CREATE INDEX staff_case_events_case ON public.staff_case_events(case_id,created_at);
CREATE TABLE public.staff_case_rules(department text PRIMARY KEY CHECK(department IN ('orders','dispatch','riders','partners','finance','support')),sla_minutes integer CHECK(sla_minutes BETWEEN 1 AND 43200),updated_by uuid,updated_at timestamptz DEFAULT now());
GRANT SELECT ON public.staff_case_rules TO authenticated; GRANT ALL ON public.staff_case_rules TO service_role; ALTER TABLE public.staff_case_rules ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Team rule read" ON public.staff_case_rules FOR SELECT TO authenticated USING(public.staff_enabled(auth.uid()) AND public.is_staff(auth.uid()));
CREATE TABLE public.staff_quality_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),case_id uuid NOT NULL REFERENCES public.staff_cases(id),member_id uuid NOT NULL,reviewer_id uuid NOT NULL,outcome text NOT NULL CHECK(outcome IN ('satisfactory','coaching','investigate','appeal')),note text NOT NULL,improvement_due date,created_at timestamptz DEFAULT now());
GRANT SELECT ON public.staff_quality_reviews TO authenticated; GRANT ALL ON public.staff_quality_reviews TO service_role; ALTER TABLE public.staff_quality_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Review scoped read" ON public.staff_quality_reviews FOR SELECT TO authenticated USING(public.staff_enabled(auth.uid()) AND (member_id=auth.uid() OR EXISTS(SELECT 1 FROM public.staff_cases c WHERE c.id=case_id AND public.staff_case_allowed(c.city_id,c.department) AND (public.has_permission(auth.uid(),'audit') OR public.has_permission(auth.uid(),'team')))));
CREATE OR REPLACE FUNCTION public.staff_case_deadline(_dept text,_at timestamptz) RETURNS timestamptz LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN EXISTS(SELECT 1 FROM staff_case_rules WHERE department=_dept) THEN (SELECT _at+sla_minutes*interval '1 minute' FROM staff_case_rules WHERE department=_dept) WHEN _dept IN ('orders','dispatch') THEN _at+interval '10 minutes' WHEN _dept='support' THEN _at+interval '30 minutes' ELSE NULL END $$;
CREATE OR REPLACE FUNCTION public.staff_set_case_rule(_department text,_minutes integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM app_owner WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Owner only'; END IF; INSERT INTO staff_case_rules(department,sla_minutes,updated_by) VALUES(_department,_minutes,auth.uid()) ON CONFLICT(department) DO UPDATE SET sla_minutes=excluded.sla_minutes,updated_by=auth.uid(),updated_at=now(); INSERT INTO staff_audit_log(actor_id,action,entity_type,entity_id,details) VALUES(auth.uid(),'rule','staff_case_rules',_department,jsonb_build_object('minutes',_minutes)); END $$;
CREATE OR REPLACE FUNCTION public.staff_case_member_allowed(_uid uuid,_city uuid,_dept text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _uid IS NOT NULL AND public.staff_enabled(_uid) AND public.has_permission(_uid,_dept) AND (EXISTS(SELECT 1 FROM user_roles WHERE user_id=_uid AND role='admin') OR EXISTS(SELECT 1 FROM staff_controls WHERE user_id=_uid AND nationwide) OR EXISTS(SELECT 1 FROM staff_scopes WHERE user_id=_uid AND city_id=_city)) $$;
CREATE OR REPLACE FUNCTION public.staff_case_action(_id uuid,_action text,_note text DEFAULT NULL,_member uuid DEFAULT NULL,_next text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c staff_cases; manager boolean; BEGIN SELECT * INTO c FROM staff_cases WHERE id=_id FOR UPDATE; IF NOT FOUND OR NOT public.staff_case_allowed(c.city_id,c.department) THEN RAISE EXCEPTION 'Case outside assigned work'; END IF; manager:=has_permission(auth.uid(),'team') OR (has_permission(auth.uid(),'audit') AND c.department<>'finance');
IF _action='claim' THEN IF c.status='resolved' OR (c.assignee_id IS NOT NULL AND c.assignee_id<>auth.uid()) THEN RAISE EXCEPTION 'Case already assigned'; END IF; IF NOT staff_case_member_allowed(auth.uid(),c.city_id,c.department) THEN RAISE EXCEPTION 'Department permission required'; END IF; UPDATE staff_cases SET assignee_id=auth.uid(),supervisor_id=(SELECT supervisor_id FROM staff_controls WHERE user_id=auth.uid()),status='in_progress',next_action=coalesce(nullif(trim(_next),''),next_action),updated_at=now() WHERE id=_id;
ELSIF _action IN ('handoff','backup') THEN IF NOT manager AND c.assignee_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Assignee or supervisor required'; END IF; IF NOT staff_case_member_allowed(_member,c.city_id,c.department) OR length(trim(coalesce(_note,'')))<3 THEN RAISE EXCEPTION 'Scoped replacement and reason required'; END IF; IF _action='handoff' THEN UPDATE staff_cases SET assignee_id=_member,supervisor_id=(SELECT supervisor_id FROM staff_controls WHERE user_id=_member),status='in_progress',updated_at=now() WHERE id=_id; ELSE UPDATE staff_cases SET backup_id=_member,updated_at=now() WHERE id=_id; END IF; PERFORM notify_user(_member,'staff_case','ٹیم کا کام تفویض ہوا',c.title,'/admin');
ELSE IF NOT manager AND c.assignee_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Assignee or supervisor required'; END IF; IF length(trim(coalesce(_note,'')))<3 THEN RAISE EXCEPTION 'Reason or resolution evidence required'; END IF;
IF _action='resolve' THEN UPDATE staff_cases SET status='resolved',resolution=left(_note,2000),resolved_at=now(),resolved_by=auth.uid(),updated_at=now() WHERE id=_id;
ELSIF _action='block' THEN UPDATE staff_cases SET status='blocked',blocked_reason=left(_note,1000),updated_at=now() WHERE id=_id;
ELSIF _action='reopen' THEN IF NOT manager THEN RAISE EXCEPTION 'Independent supervisor required'; END IF; UPDATE staff_cases SET status='open',resolved_at=NULL,resolved_by=NULL,reopen_count=reopen_count+1,updated_at=now() WHERE id=_id;
ELSIF _action='next' THEN UPDATE staff_cases SET next_action=left(_note,1000),updated_at=now() WHERE id=_id; ELSE RAISE EXCEPTION 'Unsupported action'; END IF; END IF;
INSERT INTO staff_case_events(case_id,actor_id,action,note) VALUES(_id,auth.uid(),_action,left(_note,2000)); INSERT INTO staff_audit_log(actor_id,action,entity_type,entity_id,city_id,details) VALUES(auth.uid(),_action,'staff_cases',_id::text,c.city_id,jsonb_build_object('department',c.department,'member',_member)); END $$;
CREATE OR REPLACE FUNCTION public.staff_case_review(_case uuid,_outcome text,_note text,_improvement_due date DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c staff_cases; BEGIN SELECT * INTO c FROM staff_cases WHERE id=_case FOR UPDATE; IF NOT FOUND OR NOT staff_case_allowed(c.city_id,c.department) OR length(trim(coalesce(_note,'')))<3 THEN RAISE EXCEPTION 'Scoped case and review evidence required'; END IF; IF _outcome='appeal' THEN IF c.assignee_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Only assigned member may appeal'; END IF; ELSE IF NOT (has_permission(auth.uid(),'team') OR (has_permission(auth.uid(),'audit') AND c.department<>'finance')) OR c.assignee_id=auth.uid() THEN RAISE EXCEPTION 'Independent supervisor required'; END IF; END IF; IF c.assignee_id IS NULL THEN RAISE EXCEPTION 'Assigned member required'; END IF; INSERT INTO staff_quality_reviews(case_id,member_id,reviewer_id,outcome,note,improvement_due) VALUES(_case,c.assignee_id,auth.uid(),_outcome,left(_note,2000),_improvement_due); INSERT INTO staff_case_events(case_id,actor_id,action,note) VALUES(_case,auth.uid(),'quality_'||_outcome,left(_note,2000)); END $$;
CREATE OR REPLACE FUNCTION public.staff_case_source() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j jsonb:=to_jsonb(NEW); k text:=TG_TABLE_NAME; c uuid; dept text; title text; active boolean; BEGIN IF k='support_tickets' THEN c:=staff_order_city(coalesce(NEW.order_kind,'food'),coalesce(NEW.order_id,NEW.service_booking_id)); dept:='support'; title:='شکایت کا جائزہ'; active:=NEW.status NOT IN ('resolved','closed'); ELSIF k='partner_applications' THEN c:=NEW.city_id; dept:=CASE WHEN NEW.applicant_type='rider' THEN 'riders' ELSE 'partners' END; title:='پارٹنر کی تصدیق'; active:=NEW.status='pending'; ELSIF k='rider_remittances' THEN SELECT city_id INTO c FROM riders WHERE id=NEW.rider_id; dept:='finance'; title:='نقد وصولی کی آزاد تصدیق'; active:=NEW.status='pending'; ELSE c:=(j->>'city_id')::uuid; dept:='orders'; title:='آرڈر کی نگرانی'; active:=j->>'status' NOT IN ('delivered','cancelled','returned_to_store','completed'); END IF; IF active THEN INSERT INTO staff_cases(source_kind,source_id,city_id,department,title,next_action,due_at,created_at) VALUES(k,NEW.id::text,c,dept,title,'اصل معاملہ دیکھیں',staff_case_deadline(dept,NEW.created_at),NEW.created_at) ON CONFLICT(source_kind,source_id) DO NOTHING; ELSE UPDATE staff_cases SET status='review',next_action='اصل نتیجے اور ثبوت کی تصدیق',updated_at=now() WHERE source_kind=k AND source_id=NEW.id::text AND status NOT IN ('resolved','review'); END IF; RETURN NEW; END $$;
CREATE TRIGGER staff_case_ticket AFTER INSERT OR UPDATE OF status ON public.support_tickets FOR EACH ROW EXECUTE FUNCTION public.staff_case_source(); CREATE TRIGGER staff_case_application AFTER INSERT OR UPDATE OF status ON public.partner_applications FOR EACH ROW EXECUTE FUNCTION public.staff_case_source(); CREATE TRIGGER staff_case_remittance AFTER INSERT OR UPDATE OF status ON public.rider_remittances FOR EACH ROW EXECUTE FUNCTION public.staff_case_source(); CREATE TRIGGER staff_case_food AFTER INSERT OR UPDATE OF status ON public.orders FOR EACH ROW EXECUTE FUNCTION public.staff_case_source(); CREATE TRIGGER staff_case_shop AFTER INSERT OR UPDATE OF status ON public.grocery_cart_orders FOR EACH ROW EXECUTE FUNCTION public.staff_case_source(); CREATE TRIGGER staff_case_list AFTER INSERT OR UPDATE OF status ON public.grocery_list_orders FOR EACH ROW EXECUTE FUNCTION public.staff_case_source();
CREATE OR REPLACE VIEW public.staff_case_metrics WITH(security_invoker=true) AS SELECT city_id,department,assignee_id,count(*) FILTER(WHERE status<>'resolved') open_cases,count(*) FILTER(WHERE status<>'resolved' AND due_at<now()) overdue_cases,count(*) FILTER(WHERE status='blocked') blocked_cases,count(*) FILTER(WHERE status='resolved') resolved_cases,count(*) FILTER(WHERE status='resolved' AND resolved_at<=due_at) on_time_resolved,sum(reopen_count) reopened_cases,min(created_at) FILTER(WHERE status<>'resolved') oldest_open FROM staff_cases GROUP BY city_id,department,assignee_id; GRANT SELECT ON public.staff_case_metrics TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.staff_escalate_cases() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c staff_cases; recipient uuid; n integer:=0; BEGIN FOR c IN SELECT * FROM staff_cases WHERE status<>'resolved' AND due_at<now() AND (escalation_level=0 OR (escalation_level=1 AND last_escalated_at<now()-interval '1 hour')) ORDER BY due_at LIMIT 500 FOR UPDATE SKIP LOCKED LOOP IF c.escalation_level=0 AND c.supervisor_id IS NOT NULL AND staff_case_member_allowed(c.supervisor_id,c.city_id,c.department) THEN recipient:=c.supervisor_id; ELSE SELECT user_id INTO recipient FROM app_owner LIMIT 1; END IF; IF c.assignee_id IS NOT NULL AND NOT staff_enabled(c.assignee_id) AND staff_case_member_allowed(c.backup_id,c.city_id,c.department) THEN UPDATE staff_cases SET assignee_id=c.backup_id WHERE id=c.id; END IF; PERFORM notify_user(recipient,'staff_escalation','ٹیم کا تاخیر والا کام',c.title,'/admin'); UPDATE staff_cases SET escalation_level=escalation_level+1,last_escalated_at=now() WHERE id=c.id; INSERT INTO staff_case_events(case_id,action,note) VALUES(c.id,'escalation','نگران کو اطلاع؛ تاخیر جرم کا ثبوت نہیں'); n:=n+1; END LOOP; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.staff_case_allowed(uuid,text),public.staff_case_deadline(text,timestamptz),public.staff_case_member_allowed(uuid,uuid,text),public.staff_set_case_rule(text,integer),public.staff_case_action(uuid,text,text,uuid,text),public.staff_case_review(uuid,text,text,date) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.staff_case_allowed(uuid,text),public.staff_case_deadline(text,timestamptz),public.staff_case_member_allowed(uuid,uuid,text),public.staff_set_case_rule(text,integer),public.staff_case_action(uuid,text,text,uuid,text),public.staff_case_review(uuid,text,text,date) TO authenticated,service_role; REVOKE ALL ON FUNCTION public.staff_escalate_cases(),public.staff_case_source() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.staff_escalate_cases() TO service_role;